250	    @Override
251	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
252	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
253	        if (currentOwner == null) {
254	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	        }
256	        currentOwner.setAddress(ownerFieldsDto.getAddress());
257	        currentOwner.setCity(ownerFieldsDto.getCity());
258	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
259	        currentOwner.setLastName(ownerFieldsDto.getLastName());
260	        currentOwner.setTitle(ownerFieldsDto.getTitle());
261	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
262	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
263	        this.clinicService.saveOwner(currentOwner);
264	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
265	    }
