344	
345	    /**
346	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
347	     * The address is normalized in place (so a required-field check that follows rejects an
348	     * address blank after normalization), the required fields are checked, the telephone and
349	     * email are normalized in place, and the resulting owner is rejected when its derived
350	     * identity key already belongs to another owner. Each rule
351	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
352	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
353	     * to be mapped and saved.
354	     *
355	     * @param ownerFieldsDto the submitted owner fields, normalized in place
356	     */
357	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
358	        applyAddress(ownerFieldsDto);
359	        validateRequiredFields(ownerFieldsDto);
360	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
361	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
362	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
363	        rejectDuplicateIdentity(ownerFieldsDto);
364	        rejectCityAtCapacity(ownerFieldsDto.getCity());
365	        rejectDailyLimitExceeded(registrationDate);
366	    }
367	
368	    /**
369	     * Applies an owner's address to the submitted fields, normalizing it in place into the
370	     * canonical form stored and returned for the owner. This is the single intake step that owns
371	     * how a submitted address becomes an owner's stored address: it delegates every transform to
372	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
373	     * the results back onto {@code ownerFieldsDto}.
374	     *
375	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
376	     * is present the two structured lines are normalized in place and the flat {@code address} is
377	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
378	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
379	     * every rule that later reads {@code address} sees the structured value. When no structured
380	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
381	     * backward compatibility.
382	     *
383	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
384	     * blank after normalization in either form is rejected by the required-field check that
385	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
386	     * list of named intake steps and gives address handling one place to grow.
387	     *
388	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
389	     */
390	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
391	        String line1 = ownerFieldsDto.getAddressLine1();
392	        if (line1 != null && !line1.isBlank()) {
393	            String normalizedLine1 = normalizeAddress(line1);
394	            ownerFieldsDto.setAddressLine1(normalizedLine1);
395	            String line2 = ownerFieldsDto.getAddressLine2();
396	            if (line2 != null && !line2.isBlank()) {
397	                String normalizedLine2 = normalizeAddress(line2);
398	                ownerFieldsDto.setAddressLine2(normalizedLine2);
399	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
400	            } else {
401	                ownerFieldsDto.setAddressLine2(null);
402	                ownerFieldsDto.setAddress(normalizedLine1);
403	            }
404	        } else {
405	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
406	        }
407	    }
408	
409	    /**
410	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
411	     * falls on a business day. The date supplied on the request is used when present, otherwise the
412	     * server's current date is used. When that effective date lands on a Saturday, Sunday or listed
413	     * public holiday it is rolled forward to the next non-holiday business day; a non-holiday weekday
414	     * is left unchanged. This single adjusted date
415	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
416	     * membership number's year segment, the per-day create limit) is computed against.
417	     *
418	     * A supplied registration date later than the server's current date is rejected with an
419	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
420	     *
421	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
422	     * @return the effective registration date rolled forward to the next business day
423	     */
424	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
425	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
426	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
427	            throw new InvalidFieldsException(List.of("registrationDate"));
428	        }
429	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
430	        return toBusinessDay(effective);
431	    }
432	
433	    /**
434	     * The fixed public holidays the business-day roll skips. A date landing on any of these is
435	     * advanced, along with weekends, until it reaches the next non-holiday business day.
436	     */
437	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
438	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
439	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
440	        LocalDate.parse("2026-12-28"));
441	
442	    /**
443	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public holiday is
444	     * advanced one day at a time until it reaches a weekday that is not a public holiday, while a
445	     * date already on such a business day is returned unchanged.
446	     *
447	     * @param date the date to adjust
448	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
449	     */
450	    private LocalDate toBusinessDay(LocalDate date) {
451	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
452	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
453	                || PUBLIC_HOLIDAYS.contains(date)) {
454	            date = date.plusDays(1);
455	        }
456	        return date;
457	    }
458	
459	    /**
460	     * The maximum number of owners that may be created on a single day. Once this many owners
461	     * already carry today's {@code registrationDate}, no further owner may be created today.
462	     */
463	    private static final long DAILY_OWNER_LIMIT = 100L;
464	
465	    /**
466	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
467	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
468	     * date the new owner would be stored with, so owners are capped per business day. When the limit
469	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
470	     * advice renders as a 429 Too Many Requests response.
471	     *
472	     * @param registrationDate the adjusted business-day registration date of the owner being created
473	     */
474	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
475	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
476	            throw new DailyOwnerLimitExceededException(registrationDate);
477	        }
478	    }
479	
480	    /**
481	     * Counts the existing owners whose adjusted business-day {@code registrationDate} equals the
482	     * given date. This is the single definition of the per-day owner count, shared by the per-day
483	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
484	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
485	     *
486	     * @param registrationDate the adjusted business-day registration date to count owners against
487	     * @return the number of existing owners carrying that registration date
488	     */
489	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
490	        return this.clinicService.findAllOwners().stream()
491	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
492	            .count();
493	    }
494	
495	    /**
496	     * The number of owners that may carry a single day's {@code registrationDate} before that day
497	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
498	     * the create and read responses report {@code bulkSignupWarning} true for that date.
499	     */
500	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
501	
502	    /**
503	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
504	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
505	     * count is taken against the same adjusted date owners are stored with, mirroring the
506	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
507	     *
508	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
509	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
510	     */
511	    private boolean bulkSignupWarning(LocalDate registrationDate) {
512	        if (registrationDate == null) {
513	            return false;
514	        }
