551	     * @param owner the owner being created, whose fields the code is derived from
552	     * @return the formatted customer code
553	     */
554	    private String customerCodeFor(Owner owner) {
555	        String region = owner.getRegion();
556	        String regionCode = region != null ? region : "UNKNOWN";
557	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
558	        return deduplicateCustomerCode(regionCode + "-" + hash8);
